    [3442]={name="Apprentice Sash",sourceType="quest_reward",instructions="Reward from the quest “A New Plague”. In Tirisfal Glades.",zone="Tirisfal Glades",questName="A New Plague",lore="While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims."},
    [3446]={name="Darkwood Staff",sourceType="quest_reward",instructions="Reward from the quest “The Family Crypt” — pick it over the other choices. In Tirisfal Glades.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
    [3449]={name="Mystic Shawl",sourceType="quest_reward",instructions="Reward from the quest “Pyrewood Ambush” — pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Pyrewood Ambush",lore="You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."},
    [3451]={name="Nightglow Concoction",sourceType="quest_reward",instructions="Reward from the quest “A Recipe For Death” — pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="A Recipe For Death",lore="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."},
    [3457]={name="Stamped Trousers",sourceType="quest_reward",instructions="Reward from the quest “Wand to Bethor” — pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Wand to Bethor",lore="Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed."},
