    [9603]={name="Gritroot Staff",sourceType="quest_reward",instructions="Reward from the quest “The Relics of Wakening” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
    [9609]={name="Shilly Mitts",sourceType="quest_reward",instructions="Reward from the quest “Gyrodrillmatic Excavationators” — pick it over the other choices. In Gnomeregan.",zone="Gnomeregan",questName="Gyrodrillmatic Excavationators",lore="It's terrible. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh. What we need are spare parts."},
    [9623]={name="Civinad Robes",sourceType="quest_reward",instructions="Reward from the quest “Rig Wars” — pick it over the other choices. In Gnomeregan.",zone="Gnomeregan",questName="Rig Wars",lore="Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."},
