    [10820]={name="Jackseed Belt",sourceType="quest_reward",instructions="Reward from the quest “Mura Runetotem” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
    [10821]={name="Sower's Cloak",sourceType="quest_reward",instructions="Reward from the quest “Mura Runetotem” — pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
    [10829]={name="Dragon's Eye",sourceType="boss_drop",instructions="Drops from Shade of Eranikus in Sunken Temple.",zone="Sunken Temple",npc="Shade of Eranikus",lore="What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."},
    [10836]={name="Rod of Corrosion",sourceType="boss_drop",instructions="Drops from Shade of Eranikus in Sunken Temple.",zone="Sunken Temple",npc="Shade of Eranikus",lore="What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."},
    [10843]={name="Featherskin Cape",sourceType="boss_drop",instructions="Drops from Avatar of Hakkar.",npc="Avatar of Hakkar"},
    [10919]={name="Apothecary Gloves",sourceType="quest_reward",instructions="Reward from the quest “Serpentbloom”. In Wailing Caverns.",zone="Wailing Caverns",questName="Serpentbloom",lore="A like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats."},
    [11187]={name="Stemleaf Bracers",sourceType="quest_reward",instructions="Reward from the quest “The Balance of Nature” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Balance of Nature",lore="Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."},
    [11189]={name="Woodland Robes",sourceType="quest_reward",instructions="Reward from the quest “Webwood Egg” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="Webwood Egg",lore="Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."},
    [11190]={name="Viny Gloves",sourceType="quest_reward",instructions="Reward from the quest “The Woodland Protector” — pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Woodland Protector",lore="Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."},
    [11287]={name="Lesser Magic Wand",sourceType="profession",instructions="Crafted with Enchanting (requires skill 1).",profession="Enchanting"},
