    [15397]={name="Oakthrush Staff",sourceType="quest_reward",instructions="Reward from the quest “The Fragments Within” — pick it over the other choices. In Darkshore.",zone="Darkshore",questName="The Fragments Within",lore="The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."},
    [15444]={name="Staff of Orgrimmar",sourceType="quest_reward",instructions="Reward from the quest “Hidden Enemies” — pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
    [15452]={name="Featherbead Bracers",sourceType="quest_reward",instructions="Reward from the quest “Returning the Lost Satchel” — pick it over the other choices. In Ragefire Chasm.",zone="Ragefire Chasm",questName="Returning the Lost Satchel",lore="You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."},
    [15461]={name="Lightheel Boots",sourceType="quest_reward",instructions="Reward from the quest “Protect Kanati Greycloud” — pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Protect Kanati Greycloud",lore="But, there may be more centaur than I thought, I ask you, to fight with me against these vile assassins."},
    [15468]={name="Windsong Drape",sourceType="quest_reward",instructions="Reward from the quest “Free at Last” — pick it over the other choices. In Thousand Needles.",zone="Thousand Needles",questName="Free at Last",lore="Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."},
    [15697]={name="Kodo Rustler Boots",sourceType="quest_reward",instructions="Reward from the quest “Kodo Roundup” — pick it over the other choices. In Desolace.",zone="Desolace",questName="Kodo Roundup",lore="Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership."},
