    [19115]={name="Flask of Forest Mojo",sourceType="quest_reward",instructions="Reward from the quest “Return to Primal Torntusk” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Return to Primal Torntusk",lore="Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."},
    [19116]={name="Greenleaf Handwraps",sourceType="quest_reward",instructions="Reward from the quest “Separation Anxiety” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Separation Anxiety",lore="Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."},
    [19118]={name="Nature's Breath",sourceType="quest_reward",instructions="Reward from the quest “Dark Vessels”. In The Hinterlands.",zone="The Hinterlands",questName="Dark Vessels",lore="The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."},
    [19121]={name="Deep Woodlands Cloak",sourceType="quest_reward",instructions="Reward from the quest “Wanted: Vile Priestess Hexx and Her Minions” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
    [19123]={name="Everwarm Handwraps",sourceType="quest_reward",instructions="Reward from the quest “STOLEN: Smithing Tuyere and Lookout's Spyglass” — pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="STOLEN: Smithing Tuyere and Lookout's Spyglass",lore="The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items."},
