    [21186]={name="Rockfury Bracers",sourceType="quest_reward",instructions="Reward from the quest “Stalwart's Battlegear” — pick it over the other choices. In Silithus.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21273]={name="Blessed Qiraji Acolyte Staff",sourceType="quest_reward",instructions="Reward from the quest “Imperial Qiraji Regalia” — pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Imperial Qiraji Regalia",lore="I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."},
    [21311]={name="Earth Warder's Vest",sourceType="quest_reward",instructions="Reward from the quest “Timbermaw Ally” — pick it over the other choices. In Felwood.",zone="Felwood",questName="Timbermaw Ally",lore="The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."},
    [21348]={name="Tiara of the Oracle",sourceType="quest_reward",instructions="Reward from the quest “Tiara of the Oracle”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Tiara of the Oracle",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21350]={name="Mantle of the Oracle",sourceType="quest_reward",instructions="Reward from the quest “Mantle of the Oracle”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Mantle of the Oracle",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21351]={name="Vestments of the Oracle",sourceType="quest_reward",instructions="Reward from the quest “Vestments of the Oracle”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Vestments of the Oracle",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21461]={name="Leggings of the Black Blizzard",sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21462]={name="Gloves of Dark Wisdom",sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21471]={name="Talon of Furious Concentration",sourceType="boss_drop",instructions="Drops from Moam in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Moam",lore="A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."},
    [21507]={name="Amulet of the Shifting Sands",sourceType="quest_reward",instructions="Reward from the quest “The Fall of Ossirian” — pick it over the other choices. In Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",questName="The Fall of Ossirian",lore="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."},
    [21565]={name="Rune of Perfection",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21566]={name="Rune of Perfection",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21583]={name="Cloak of Clarity",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21585]={name="Dark Storm Gauntlets",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21597]={name="Royal Scepter of Vek'lor",sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21600]={name="Boots of Epiphany",sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21603]={name="Wand of Qiraji Nobility",sourceType="boss_drop",instructions="Drops from Lord Kri in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Lord Kri",lore="One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."},
    [21604]={name="Bracelets of Royal Redemption",sourceType="boss_drop",instructions="Drops from Emperor Vek'nilash in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'nilash",lore="Twin emperor of the qiraji, and the stronger arm of the pair. Kill one and the other heals him, so both must fall together."},
    [21608]={name="Amulet of Vek'nilash",sourceType="boss_drop",instructions="Drops from Emperor Vek'nilash in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'nilash",lore="Twin emperor of the qiraji, and the stronger arm of the pair. Kill one and the other heals him, so both must fall together."},
