    [22512]={name="Robe of Faith",sourceType="quest_reward",instructions="Reward from the quest “Robe of Faith”. In Naxxramas.",zone="Naxxramas",questName="Robe of Faith",lore="The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity. Bring me the desecrated remnants of the departed along with reagents of purification and you shall know faith."},
