    [23027]={name="Warmth of Forgiveness",sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease",proc="Use: Restores 500 mana. (3 Min Cooldown)"},
    [23029]={name="Noth's Frigid Heart",sourceType="boss_drop",instructions="Drops from Noth the Plaguebringer in Naxxramas.",zone="Naxxramas",npc="Noth the Plaguebringer",lore="A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."},
